import sys

def main():
    import sys
    import math

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    T = readints()[0]
    results = []

    for _ in range(T):
        N, K = readints()
        # Calculate the minimum number of pizzas needed
        pizzas_needed = math.ceil(N / K)
        results.append(pizzas_needed)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
